def is_kawaii(seq):
    # The sequence is kawaii if for each k >= 2,
    # if k is in the sequence, then k-1 is also in the sequence,
    # and the first occurrence of k-1 comes before the last occurrence of k.
    max_val = max(seq)
    for k in range(2, max_val + 1):
        if k in seq:
            if (k-1) not in seq:
                return False
            first_k_minus_1 = seq.index(k-1)
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 > last_k:
                return False
    return True

def count_kawaii(n):
    import itertools
    count = 0
    # The sequence elements must be from {1, 2, ..., n}
    # because a kawaii sequence of length n can have at most n distinct values,
    # and if it has m distinct values, they must be {1, 2, ..., m}.
    # Wait, the values can be any positive integers.
    # However, if the values are {v_1, v_2, ..., v_m}, they must be {1, 2, ..., m}
    # because if v_m is the max, then v_m-1, ..., 1 must also be there.
    # So for a fixed m, we are looking for sequences of length n using values {1, ..., m}
    # where each value from {1, ..., m} appears at least once.
    # For a fixed m, let's count how many such sequences are kawaii.

    total_kawaii = 0
    for m in range(1, n + 1):
        # sequences of length n using values {1, ..., m}
        # such that each value 1...m appears at least once.
        for seq in itertools.product(range(1, m + 1), repeat=n):
            if len(set(seq)) == m:
                if is_kawaii(seq):
                    total_kawaii += 1
    return total_kawaii

